import os
import base64
from dataclasses import dataclass
from typing import Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeEncryptedBlob:
    kms_key_id: str
    encrypted_data_key: bytes
    nonce: bytes
    ciphertext: bytes
    tag: bytes

    def serialize(self) -> dict:
        return {
            "kms_key_id": self.kms_key_id,
            "encrypted_data_key": base64.b64encode(self.encrypted_data_key).decode("utf-8"),
            "nonce": base64.b64encode(self.nonce).decode("utf-8"),
            "ciphertext": base64.b64encode(self.ciphertext).decode("utf-8"),
            "tag": base64.b64encode(self.tag).decode("utf-8"),
        }

    @classmethod
    def deserialize(cls, data: dict) -> "EnvelopeEncryptedBlob":
        return cls(
            kms_key_id=data["kms_key_id"],
            encrypted_data_key=base64.b64decode(data["encrypted_data_key"]),
            nonce=base64.b64decode(data["nonce"]),
            ciphertext=base64.b64decode(data["ciphertext"]),
            tag=base64.b64decode(data["tag"]),
        )


class AWSEnvelopeEncryptor:
    def __init__(self, kms_key_id: str, region_name: Optional[str] = None):
        self.kms_key_id = kms_key_id
        self.kms = boto3.client("kms", region_name=region_name or os.getenv("AWS_REGION"))
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except ImportError as exc:
            raise ImportError("cryptography is required for local data encryption/decryption") from exc
        self._aesgcm_cls = AESGCM

    def encrypt(self, plaintext: Union[bytes, str], encryption_context: Optional[dict] = None) -> dict:
        if isinstance(plaintext, str):
            plaintext = plaintext.encode("utf-8")

        try:
            resp = self.kms.generate_data_key(
                KeyId=self.kms_key_id,
                KeySpec="AES_256",
                EncryptionContext=encryption_context or {},
            )
            plaintext_data_key = resp["Plaintext"]
            encrypted_data_key = resp["CiphertextBlob"]

            aesgcm = self._aesgcm_cls(plaintext_data_key)
            nonce = os.urandom(12)
            aad = self._serialize_context(encryption_context)
            ct = aesgcm.encrypt(nonce, plaintext, aad)
            ciphertext, tag = ct[:-16], ct[-16:]

            return EnvelopeEncryptedBlob(
                kms_key_id=self.kms_key_id,
                encrypted_data_key=encrypted_data_key,
                nonce=nonce,
                ciphertext=ciphertext,
                tag=tag,
            ).serialize()
        except (BotoCoreError, ClientError) as exc:
            raise RuntimeError(f"AWS KMS envelope encryption failed: {exc}") from exc

    def decrypt(self, blob: dict, encryption_context: Optional[dict] = None) -> bytes:
        payload = EnvelopeEncryptedBlob.deserialize(blob)
        if encryption_context and blob.get("kms_key_id") and blob["kms_key_id"] != self.kms_key_id:
            raise ValueError("Provided KMS key ID does not match encrypted blob key ID")

        try:
            resp = self.kms.decrypt(
                CiphertextBlob=payload.encrypted_data_key,
                EncryptionContext=encryption_context or {},
            )
            plaintext_data_key = resp["Plaintext"]

            aesgcm = self._aesgcm_cls(plaintext_data_key)
            aad = self._serialize_context(encryption_context)
            ct = payload.ciphertext + payload.tag
            return aesgcm.decrypt(payload.nonce, ct, aad)
        except (BotoCoreError, ClientError) as exc:
            raise RuntimeError(f"AWS KMS envelope decryption failed: {exc}") from exc

    @staticmethod
    def _serialize_context(encryption_context: Optional[dict]) -> Optional[bytes]:
        if not encryption_context:
            return None
        items = sorted((str(k), str(v)) for k, v in encryption_context.items())
        return "&".join(f"{k}={v}" for k, v in items).encode("utf-8")
